import{_ as e,c as t,o as s,a4 as a}from"./chunks/framework.P4k6vdAm.js";const f=JSON.parse('{"title":"How the Endpoint Response is Decided","description":"","frontmatter":{},"headers":[],"relativePath":"docs/building/endpoint-response.md","filePath":"docs/building/endpoint-response.md","lastUpdated":1793099931000}'),o={name:"docs/building/endpoint-response.md"},i=a('<h1 id="how-the-endpoint-response-is-decided" tabindex="-1">How the Endpoint Response is Decided <a class="header-anchor" href="#how-the-endpoint-response-is-decided" aria-label="Permalink to &quot;How the Endpoint Response is Decided&quot;">​</a></h1><p>Each task produces its own result and status code, but the endpoint&#39;s HTTP response isn&#39;t simply the last task&#39;s. After the tasks have run, the response is chosen in this order - the first match wins:</p><ol><li><strong><a href="/docs/tasks/http-redirect.html">HTTP Redirect</a> task</strong> - the caller is redirected.</li><li><strong>Task with <a href="/docs/tasks/http-request.html#retain-status-code"><code>Retain status code</code></a> enabled</strong> - that task&#39;s status code is returned, with the HTTP Response task&#39;s body and headers if there is one, otherwise that task&#39;s own body.</li><li><strong><a href="/docs/tasks/http-response.html">HTTP Response</a> task</strong> - its configured status code, body and headers.</li><li><strong>Otherwise:</strong><ul><li>if <code>Stop on Task Failure</code> stopped the endpoint, the failed task&#39;s status code and body.</li><li>if not, <code>200</code> with <a href="/docs/tasks/http-response.html#omitting-this-task">the results of every task</a>. This includes when tasks failed but <code>Stop on Task Failure</code> is off.</li></ul></li></ol><h2 id="which-tasks-count" tabindex="-1">Which tasks count <a class="header-anchor" href="#which-tasks-count" aria-label="Permalink to &quot;Which tasks count&quot;">​</a></h2><ul><li><p>Tasks that were never reached, because <code>Stop on Task Failure</code> stopped the endpoint first, are ignored.</p></li><li><p>Skipped tasks still count, and return a <code>200</code> with a result that says why they were skipped:</p><ul><li><code>Disabled by filter - behaviour was not run</code>: one of the task&#39;s <a href="/docs/building/working-with-data.html#filters">filters</a> evaluated to <code>false</code>. For JSONPath filters, this means the path didn&#39;t match anything in the data.</li><li><code>Disabled - behaviour was not run</code>: the task is disabled in the endpoint editor.</li></ul><p>So if a skipped task has <code>Retain status code</code> enabled, the endpoint returns <code>200</code>, even if an earlier task that ran returned something else. And if the endpoint has no HTTP Response task, these messages appear in the results it returns.</p></li></ul><p>As <code>Stop on Task Failure</code> is on by default, a failing task&#39;s status code is usually what&#39;s returned - it halts the endpoint before any later HTTP Response task runs.</p><h2 id="other-cases" tabindex="-1">Other cases <a class="header-anchor" href="#other-cases" aria-label="Permalink to &quot;Other cases&quot;">​</a></h2><ul><li>An endpoint with no HTTP Request, HTTP Response, HTTP Redirect, SMS, Fax or PDF tasks (e.g. only Mapping or Email tasks) always returns the results of every task, even when <code>Stop on Task Failure</code> stopped it.</li><li>If a task raises an error rather than failing (for example an <a href="/docs/tasks/http-response-handler.html">HTTP Response Handler</a> schema validation failure), an error response is returned instead.</li></ul>',8),n=[i];function d(r,h,l,c,p,u){return s(),t("div",null,n)}const T=e(o,[["render",d]]);export{f as __pageData,T as default};
